/** How many bytes a whole `message` needs, given `have` of them.
 *
 * SITU_OK            a complete one is present; *need is its length
 * SITU_ERR_TRUNCATED not yet; *need is a lower bound on the total
 *
 * For framing a stream: read, ask, read the difference, ask again. The
 * length fields are read only once the bytes holding them have arrived,
 * which is the case every hand-written version of this gets wrong.
 */
static inline situ_err_t fzn_stickers_local_message_required(const uint8_t *data, uint32_t have, uint32_t *need)
{
	uint32_t at = 2u;
	uint32_t pos = 2u;
	situ_view_t view;

	/* A view over what has arrived, so every length expression below
	 * reads through the same bounds the accessors do. */
	view.base       = (uint8_t *)(uintptr_t)(const void *)data;
	view.limit      = have;
	view.generation = 0u;
	view.owner      = NULL;

	/* message.body: reading its length means reading bytes that
	 * have to be here first. */
	if (have < 2u) {
		*need = at;
		return SITU_ERR_TRUNCATED;
	}

	/* message.body: the arm the discriminant selects frames
	 * itself. Its EXTENT shrinks when the bytes run out, so
	 * adding that reported a complete message -- reported by
	 * bbq-predictor against a variant arm (26.684). */
	{
		uint32_t   part = 0u;
		situ_err_t e = SITU_OK;

		if (fzn_stickers_local_message_op_get(view) == 128u) {
			e = fzn_stickers_local_nothing_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 129u) {
			e = fzn_stickers_local_pack_row_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 130u) {
			e = fzn_stickers_local_pack_ask_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 131u) {
			e = fzn_stickers_local_item_row_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 132u) {
			e = fzn_stickers_local_keep_ask_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 133u) {
			e = fzn_stickers_local_kept_row_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 134u) {
			e = fzn_stickers_local_pack_ask_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 135u) {
			e = fzn_stickers_local_reference_ask_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 136u) {
			e = fzn_stickers_local_referenced_row_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 137u) {
			e = fzn_stickers_local_art_ask_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 138u) {
			e = fzn_stickers_local_drawn_row_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 139u) {
			e = fzn_stickers_local_put_ask_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 140u) {
			e = fzn_stickers_local_nothing_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 141u) {
			e = fzn_stickers_local_recent_row_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 142u) {
			e = fzn_stickers_local_match_ask_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		} else if (fzn_stickers_local_message_op_get(view) == 143u) {
			e = fzn_stickers_local_match_row_required(data + pos,
			                situ_remaining_u32(have, pos), &part);
			if (e != SITU_OK) {
				*need = situ_need_u32(at, part);
				return SITU_ERR_TRUNCATED;
			}
		}
		(void)e;
		at = situ_need_u32(at, part);
	}

	*need = at;
	return have >= at ? SITU_OK : SITU_ERR_TRUNCATED;
}

/** Writing any of these changes where later members start, so each
 * one bumps the message generation and invalidates outstanding
 * views. In a SITU_CHECKED build a stale view is then caught on
 * use; in a release build the check compiles out.
 */
static inline void fzn_stickers_local_message_op_set(situ_msg_t *msg, situ_view_t view, fzn_stickers_local_op_t value)
{
	(situ_base(view))[1u] = (uint8_t)value;
	situ_msg_touch(msg);
}

/** Check every constraint this schema states: [must_eq], [max],
 * [min], and the reserved-bit policy. Called on parse under
 * SITU_CHECKED, and available explicitly in any build.
 */
situ_err_t fzn_stickers_local_message_validate(situ_view_t view);

/** The same walk, naming the member that refused. `*which` is one
 * of the ids below on a refusal and 0xFFFFFFFF when nothing
 * refused -- it is written either way, so a caller must not
 * expect its own value to survive the call. NULL asks for
 * the verdict alone. The id is the contract and the name is
 * a macro, so nothing here costs a string (0051).
 */
situ_err_t fzn_stickers_local_message_check(situ_view_t view, uint32_t *which);
